//! `Compressor` vs Chromium's `DynamicsCompressorNode` (`rune/parity/fixtures/fx_compressor.json`,
//! captured by rune/parity/chromium/capture-compressor.steps.mjs): every case is replayed (input
//! regenerated by `gen_signal`, params applied at the scripted quanta, `reduction` read before
//! each step's changes) and compared through the block evidence of stats.mjs.

use super::*;
use mdaw_dsp::factory::Mulberry32;
use serde_json::Value;

const BLOCK: usize = 1024;
const PROJ: usize = 16;
const PROJ_SEED: u32 = 0x9a0f_0001;
/// Required full-render error (error energy / signal energy, both channels).
const MAX_ERR_DB: f64 = -60.0;
/// Required per-block energy agreement where the reference block is above the level floor.
const MAX_BLOCK_ENERGY_DB: f64 = 0.5;
const LEVEL_FLOOR_DB: f64 = -100.0;
const QUANTUM: usize = 128;

fn fixture() -> Value {
    let p = format!(
        "{}/../../parity/fixtures/fx_compressor.json",
        env!("CARGO_MANIFEST_DIR")
    );
    serde_json::from_str(&std::fs::read_to_string(&p).expect("fx_compressor.json")).unwrap()
}

fn f(v: &Value) -> f64 {
    v.as_f64().unwrap()
}

/// `genSignal` of capture-compressor.steps.mjs.
fn gen_signal(parts: &Value, frames: usize, sr: f64) -> [Vec<f32>; 2] {
    let mut out = [vec![0f64; frames], vec![0f64; frames]];
    let two_pi = 2.0 * std::f64::consts::PI;
    for p in parts.as_array().unwrap() {
        for (ch, x) in out.iter_mut().enumerate() {
            let g = f(&p["amp"][ch]);
            let start = (f(&p["at"]) * sr).round() as usize;
            match p["k"].as_str().unwrap() {
                "sine" => {
                    let end = frames.min((f(&p["end"]) * sr).round() as usize);
                    let (freq, phase) = (f(&p["freq"]), f(&p["phase"][ch]));
                    for (i, v) in x.iter_mut().enumerate().take(end).skip(start) {
                        *v += g * (two_pi * freq * ((i - start) as f64 / sr) + phase).sin();
                    }
                }
                kind => {
                    let period = (f(&p["period"]) * sr).round() as usize;
                    let count = p["count"].as_u64().unwrap() as usize;
                    let end = frames.min(start + count * period);
                    let decay = f(&p["decay"]);
                    let mut rng = (kind == "noise").then(|| {
                        Mulberry32::new(
                            (p["seed"].as_u64().unwrap() as u32).wrapping_add(ch as u32),
                        )
                    });
                    let freq = p["freq"].as_f64().unwrap_or(0.0);
                    for (i, v) in x.iter_mut().enumerate().take(end).skip(start) {
                        let tt = ((i - start) % period) as f64 / sr;
                        let env = (-tt / decay).exp();
                        *v += match &mut rng {
                            Some(r) => g * (r.next_f64() * 2.0 - 1.0) * env,
                            None => g * env * (two_pi * freq * tt).sin(),
                        };
                    }
                }
            }
        }
    }
    out.map(|x| x.into_iter().map(|v| v as f32).collect())
}

fn params_of(v: &Value, base: CompressorParams) -> CompressorParams {
    let get = |k: &str, d: f32| v.get(k).map_or(d, |x| x.as_f64().unwrap() as f32);
    CompressorParams {
        threshold: get("threshold", base.threshold),
        knee: get("knee", base.knee),
        ratio: get("ratio", base.ratio),
        attack: get("attack", base.attack),
        release: get("release", base.release),
    }
}

struct Rendered {
    channels: [Vec<f32>; 2],
    reduction: Vec<f32>,
}

fn render_case(case: &Value) -> Rendered {
    let sr = f(&case["sr"]);
    let frames = case["frames"].as_u64().unwrap() as usize;
    let [mut l, mut r] = gen_signal(&case["signal"], frames, sr);
    let mut p = params_of(&case["params"], CompressorParams::default());
    let mut steps = case["steps"].as_array().unwrap().iter().peekable();
    let mut comp = Compressor::new(sr as f32);
    let mut reduction = Vec::new();
    for start in (0..frames).step_by(QUANTUM) {
        while let Some(s) = steps.next_if(|s| s["frame"].as_u64().unwrap() as usize == start) {
            reduction.push(comp.reduction());
            p = params_of(&s["set"], p);
        }
        let end = frames.min(start + QUANTUM);
        comp.process(&mut l[start..end], &mut r[start..end], &p);
    }
    assert!(steps.next().is_none(), "unreached steps");
    Rendered {
        channels: [l, r],
        reduction,
    }
}

/// `blockEvidence` of stats.mjs.
fn block_evidence(x: &[f32]) -> Vec<[f64; PROJ + 1]> {
    let mut rng = Mulberry32::new(PROJ_SEED);
    x.chunks(BLOCK)
        .map(|b| {
            let mut out = [0f64; PROJ + 1];
            out[0] = b.iter().map(|&v| v as f64 * v as f64).sum();
            for p in &mut out[1..] {
                for w in b.chunks(32) {
                    let word = (rng.next_f64() * 4_294_967_296.0) as u32;
                    for (t, &v) in w.iter().enumerate() {
                        let v = v as f64;
                        *p += if (word >> t) & 1 == 1 { -v } else { v };
                    }
                }
            }
            out
        })
        .collect()
}

/// (error energy, signal energy, worst block energy difference in dB) of one channel.
fn channel_error(x: &[f32], reference: &[f64]) -> (f64, f64, f64) {
    let ours = block_evidence(x);
    assert_eq!(ours.len() * (PROJ + 1), reference.len(), "evidence size");
    let floor = 10f64.powf(LEVEL_FLOOR_DB / 10.0);
    let (mut err, mut sig, mut worst) = (0.0, 0.0, 0f64);
    for (i, (o, r)) in ours.iter().zip(reference.chunks(PROJ + 1)).enumerate() {
        let len = BLOCK.min(x.len() - i * BLOCK) as f64;
        err += (1..=PROJ).map(|k| (o[k] - r[k]).powi(2)).sum::<f64>() / PROJ as f64;
        sig += r[0];
        if r[0] / len >= floor {
            worst = worst.max((10.0 * (o[0].max(1e-300) / r[0]).log10()).abs());
        }
    }
    (err, sig, worst)
}

#[test]
fn compressor_matches_chromium() {
    let fx = fixture();
    let mut failures = Vec::new();
    eprintln!(
        "{:>18} {:>6} {:>12} {:>16} {:>14}",
        "case", "sr", "full err dB", "worst blk ΔdB", "max Δreduction"
    );
    for case in fx["cases"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let r = render_case(case);
        let (mut err, mut sig, mut worst) = (0.0, 0.0, 0f64);
        for (ch, e) in r.channels.iter().zip(case["evidence"].as_array().unwrap()) {
            let reference: Vec<f64> = e.as_array().unwrap().iter().map(f).collect();
            let (e, s, w) = channel_error(ch, &reference);
            err += e;
            sig += s;
            worst = worst.max(w);
        }
        let db = 10.0 * (err.max(1e-300) / sig).log10();
        let reds = case["reduction"].as_array().unwrap();
        assert_eq!(reds.len(), r.reduction.len(), "{id}: reduction reads");
        let dred = reds
            .iter()
            .zip(&r.reduction)
            .map(|(a, &b)| (f(a) - b as f64).abs() / f(a).abs().max(1.0))
            .fold(0f64, f64::max);
        eprintln!(
            "{id:>18} {:>6} {db:>12.1} {worst:>16.2e} {dred:>14.2e}",
            case["sr"]
        );
        if db > MAX_ERR_DB || worst > MAX_BLOCK_ENERGY_DB || dred > 1e-3 {
            failures.push(format!(
                "{id}: {db:.1} dB, worst block {worst:.3} dB, reduction {dred:.2e}"
            ));
        }
    }
    assert!(failures.is_empty(), "{failures:?}");
}

/// Sample-level comparison against raw captures (`PARITY_DEBUG_DIR`, see the steps script).
#[test]
#[ignore]
fn compressor_parity_debug() {
    let Ok(dir) = std::env::var("PARITY_DEBUG_DIR") else {
        return;
    };
    let fx = fixture();
    for case in fx["cases"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let Ok(bytes) = std::fs::read(format!("{dir}/{id}.f32")) else {
            continue;
        };
        let raw: Vec<f32> = bytes
            .as_chunks::<4>()
            .0
            .iter()
            .map(|b| f32::from_le_bytes(*b))
            .collect();
        let frames = raw.len() / 2;
        let r = render_case(case);
        let input = std::fs::read(format!("{dir}/{id}.in.f32")).unwrap();
        let ours_in = gen_signal(&case["signal"], frames, f(&case["sr"]));
        let in_diff = input
            .as_chunks::<4>()
            .0
            .iter()
            .map(|b| f32::from_le_bytes(*b))
            .zip(ours_in.iter().flatten())
            .filter(|(a, b)| a != *b)
            .count();
        let mut first = None;
        let mut diff = 0usize;
        let mut max = 0f32;
        for (ch, ours) in r.channels.iter().enumerate() {
            for (i, (&a, &b)) in raw[ch * frames..(ch + 1) * frames]
                .iter()
                .zip(ours)
                .enumerate()
            {
                if a != b {
                    diff += 1;
                    max = max.max((a - b).abs());
                    first.get_or_insert((ch, i, a, b));
                }
            }
        }
        eprintln!("{id}: input diffs {in_diff}, output diffs {diff}, max {max:e}, first {first:?}");
    }
}

#[test]
fn process_does_not_allocate() {
    let mut c = Compressor::new(48000.0);
    let (mut l, mut r) = (vec![0.5f32; 128], vec![-0.25f32; 128]);
    let p = CompressorParams::default();
    c.process(&mut l, &mut r, &p);
    let n = crate::test_alloc::allocations_during(|| {
        for i in 0..50 {
            let q = CompressorParams {
                threshold: -(i as f32),
                ..p
            };
            c.process(&mut l, &mut r, &q);
        }
    });
    assert_eq!(n, 0);
}

#[test]
fn reset_matches_fresh_node() {
    let input: Vec<f32> = (0..1024).map(|i| ((i as f32) * 0.05).sin() * 0.9).collect();
    let run = |c: &mut Compressor| {
        let (mut l, mut r) = (input.clone(), input.clone());
        for (a, b) in l.chunks_mut(128).zip(r.chunks_mut(128)) {
            c.process(a, b, &CompressorParams::default());
        }
        (l, c.reduction())
    };
    let mut c = Compressor::new(48000.0);
    let first = run(&mut c);
    c.reset();
    assert_eq!(c.reduction(), 0.0);
    assert_eq!(run(&mut c), first);
}
